            return ((self.weak.get()).?.asPromise()).?;
    }

pub fn getOrNull(self: @This()) ?*jsc.JSPromise {
            const promise_value = ((self.weak.get()) orelse { return null; });
            return promise_value.asPromise();
    }

pub fn value(self: @This()) JSValue {
            return (self.weak.get()).?;
    }

pub fn valueOrEmpty(self: @This()) JSValue {
            return ((self.weak.get()) orelse (.zero));
    }

pub fn swap(self: *@This()) *jsc.JSPromise {
            const prom = (self.weak.swap().asPromise()).?;
            _ = self.weak.deinit();
            return prom;
    }

pub fn deinit(self: *@This()) void {
            _ = self.weak.clear();
            _ = self.weak.deinit();
    }
    const WeakType = @This();
};
}
